js3m2.solucao:
const pontos = Number(prompt("Quantos pontos você fez?"));

if (pontos >= 1000) {
  console.log("Medalha de ouro!");
  console.log("Você chegou ao topo do ranking.");
} else if (pontos >= 500) {
  console.log("Medalha de prata!");
  console.log(`Faltam ${1000 - pontos} pontos para o ouro.`);
} else if (pontos >= 100) {
  console.log("Medalha de bronze!");
  console.log(`Faltam ${500 - pontos} pontos para a prata.`);
} else {
  console.log("Sem medalha desta vez.");
  console.log(`Faltam ${100 - pontos} pontos para o bronze.`);
}

