const casos = [[0, "pedra"], [0.3, "pedra"], [0.34, "papel"], [0.5, "papel"], [0.66, "papel"], [0.7, "tesoura"], [0.99, "tesoura"]];
for (const [valor, nome] of casos) {
  const r = rodar(["papel"], { aleatorios: [valor], contexto: `Com a jogada 'papel' e Math.random() devolvendo ${valor}` });
  const primeira = r.linhas[0];
  verificar(primeira === `Computador jogou: ${nome}`,
    `Com Math.random() devolvendo ${valor}, Math.floor(${valor} * 3) dá ${Math.floor(valor * 3)}, então a primeira linha deveria ser "Computador jogou: ${nome}", mas foi ${primeira === undefined ? "nada (o programa não mostrou nenhuma linha)" : mostrar(primeira)}. Sorteie uma vez só, com Math.floor(Math.random() * 3), e use 0 = pedra, 1 = papel, 2 = tesoura.`);
}

const ganhaDe = { pedra: "tesoura", tesoura: "papel", papel: "pedra" };
const sorteios = [[0.1, "pedra"], [0.5, "papel"], [0.9, "tesoura"]];
for (const jogada of ["pedra", "papel", "tesoura"]) {
  for (const [valor, pc] of sorteios) {
    const esperado = jogada === pc ? "Empate!" : ganhaDe[jogada] === pc ? "Você venceu!" : "Você perdeu!";
    const r = rodar([jogada], { aleatorios: [valor], contexto: `Com a jogada '${jogada}' e o computador jogando ${pc}` });
    saidaIgual(r, [`Computador jogou: ${pc}`, esperado]);
  }
}

js3m6.solucao:
const jogada = prompt("Pedra, papel ou tesoura?");

if (jogada !== "pedra" && jogada !== "papel" && jogada !== "tesoura") {
  console.log(`Jogada inválida: ${jogada}`);
} else {
  const sorteio = Math.floor(Math.random() * 3);
  let computador;
  switch (sorteio) {
    case 0:
      computador = "pedra";
      break;
    case 1:
      computador = "papel";
      break;
    default:
      computador = "tesoura";
  }
  console.log(`Computador jogou: ${computador}`);

  if (jogada === computador) {
    console.log("Empate!");
  } else if (
    (jogada === "pedra" && computador === "tesoura") ||
    (jogada === "tesoura" && computador === "papel") ||
    (jogada === "papel" && computador === "pedra")
  ) {
    console.log("Você venceu!");
  } else {
    console.log("Você perdeu!");
  }
}
